// Pick the one article this run publishes, out of the curator's backlog.
//
// Topic rotation, added when content_queue became a durable backlog: the curator used to
// hand over a fresh five-item slate whose diversity caps were fought over inside a single
// run, and the four it did not publish were expired. Now it just tops the backlog up, and
// variety is decided here instead - where it can be guaranteed across a week rather than
// inside one slate. Skipping the topics of the last AVOID_LAST published posts is enough:
// it is deterministic, needs no state of its own, and costs nothing.
//
// Deliberately NOT random. Random selection would throw away the ranking the curator paid
// an LLM to produce, and it only pays for itself as exploration - which needs a reward
// signal. Nothing reads LinkedIn engagement back into this sheet yet, so there is nothing
// to explore against. Revisit if that changes.
// AVOID_LAST must leave at least TWO categories eligible, or rotation stops being a
// tiebreak and becomes a strict round-robin that overrides the ranking entirely. It was 2
// while the curator ran five categories; the curator now runs three (Data/AI/DevOps), so 2
// would leave exactly one eligible category and a VERY_HIGH row would wait behind a LOW one
// purely because of publish order. At 1 the same topic can never go out twice in a row -
// which is the whole point - and PRIORITY still chooses between the other two.
const AVOID_LAST = 1;

const priorityOrder = {
  VERY_HIGH: 0,
  HIGH: 1,
  MEDIUM: 2,
  LOW: 3
};
const topicOf = (r) => String(r.TOPIC || '').trim();
const byPriorityThenRow = (a, b) => {
  const aPriority = priorityOrder[a.PRIORITY] ?? 4;
  const bPriority = priorityOrder[b.PRIORITY] ?? 4;
  if (aPriority !== bPriority) {
    return aPriority - bPriority; // sort by priority
  }
  return a.row_number - b.row_number; // sort by row_number ascending
};

const rows = $input.all().map((item) => item.json).filter((item) => item && item.URL);

// Most recently published first. RELEASE_DATE is written by update_status_published_a;
// rows that predate it fall back to UPDATE_DATE so the rotation still sees them.
const recentTopics = rows
  .filter((r) => /^PUBLISHED$/.test(String(r.STATUS || '').trim()))
  .map((r) => ({ topic: topicOf(r), at: Date.parse(r.RELEASE_DATE || '') || Date.parse(r.UPDATE_DATE || '') || 0 }))
  .filter((r) => r.topic && r.at)
  .sort((a, b) => b.at - a.at)
  .slice(0, AVOID_LAST)
  .map((r) => r.topic);

const queue = rows.filter((item) => /^(QUEUE)$/.test(item.STATUS)).toSorted(byPriorityThenRow);
const rotated = queue.filter((r) => !recentTopics.includes(topicOf(r)));

// Rotation must never be the reason nothing gets published: if every queued row is on a
// topic we just covered, publish the best one anyway rather than skipping the slot.
const pool = rotated.length ? rotated : queue;
console.log(
  'select_article_to_post: ' + queue.length + ' queued, avoiding [' + recentTopics.join(', ') + '], ' +
    rotated.length + ' on a fresh topic' + (rotated.length ? '' : ' - rotation relaxed to fill the slot')
);

return pool.slice(0, 1);

